/// Decode a style-token list op (u16 count followed by u16 token IDs).
pub fn style_tokens(style: &mut StyleRefinement, r: &mut R) {
    for _ in 0..r.u16() {
        let t = r.u16();
        if !style_token(style, t) {
            bad_op("Styled", t);
        }
    }
}
